29		<link rel="icon" href="data:image/svg+xml,%3Csvg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'%3E%3Ctext y='.9em' font-size='90'%3E👋%3C/text%3E%3C/svg%3E">
30		<style>
31			:root {
32				color-scheme: light dark;
33				--text: #1a1a1a;
34				--text-secondary: #555;
35				--background: #fff;
36				--surface: #f9f9f9;
