113				text-wrap: balance;
114				margin: 2rem 0 1rem 0;
115				letter-spacing: -0.01em;
116			}
117			h2:first-child {
118				margin-top: 0;
119			}
120			p {
121				text-wrap: pretty;
122				margin: 1rem 0;
123				line-height: 1.65;
