147			button,
148			.button {
149				display: inline-block;
150				text-decoration: none;
151				padding: 0.75rem 1.5rem;
152				font-size: 1rem;
153				font-weight: 500;
154				font-family: inherit;
155				color: var(--background);
156				background: var(--accent);
