203				outline: 3px solid var(--text);
204				outline-offset: -3px;
205			}
206			header {
207				padding-block: 1.5rem 0;
208			}
209			nav ul {
210				display: flex;
211				flex-wrap: wrap;
212				gap: 0.5rem 1.5rem;
213				margin: 1rem 0 0 0;
214				padding: 0;
215				list-style: none;
216			}
217			nav li {
218				margin: 0;
219			}
220			footer nav ul {
221				justify-content: center;
222				margin: 0 0 1rem 0;
223			}
224			main {
225				padding: 1rem 0;
226			}
227			main:focus {
228				outline: none;
229			}
230			section {
231				margin: 2rem 0;
232			}
233			[id] {
234				scroll-margin-top: 1.5rem;
235			}
