265				overflow: hidden;
266				clip: rect(0, 0, 0, 0);
267				white-space: nowrap;
268				border: 0;
269			}
270			@media (prefers-contrast: more) {
271				:root {
272					--border: currentColor;
273					--border-control: currentColor;
274				}
275				button,
276				.button {
277					border-width: 3px;
