281				}
282			}
283			footer {
284				padding-block: 1.5rem;
285				border-top: 1px solid var(--border);
286				font-size: 0.875rem;
287				color: var(--text-secondary);
288				text-align: center;
289			}
290			footer p {
291				margin: 0.5rem 0;
292			}
293			small {
294				display: block;
295			}
296			kbd {
297				background: var(--surface);
298				border: 1px solid var(--border);
299				border-radius: 0.25rem;
300				padding: 0.125rem 0.375rem;
301				font-family: monospace;
302				font-size: 0.875em;
303			}
304			.field {
305				margin-bottom: 1rem;
306			}
307			label {
308				display: block;
309				margin-bottom: 0.5rem;
310				font-weight: 500;
311			}
312			input,
313			textarea {
314				width: 100%;
315				padding: 0.5rem;
316				font: inherit;
317				color: var(--text);
318				background: var(--surface);
319				border: 1px solid var(--border-control);
320				border-radius: 0.25rem;
321				transition: border-color 0.15s ease, box-shadow 0.15s ease;
322			}
323			textarea {
324				resize: vertical;
325			}
326			#form-status {
327				margin: 0;
328			}
329			#form-status:not(:empty) {
330				margin-top: 1rem;
331				padding: 0.75rem 1rem;
332				border-radius: 0.25rem;
333				background: color-mix(in srgb, var(--success) 10%, transparent);
334				color: var(--success);
335				border: 1px solid var(--success);
336			}
337			.form-hint {
338				margin: 0 0 1rem 0;
339				font-size: 0.875rem;
340				color: var(--text-secondary);
341			}
342			.field .form-hint {
343				margin: 0.25rem 0 0 0;
344			}
345			input:user-invalid,
346			textarea:user-invalid,
347			[aria-invalid="true"] {
348				border-color: var(--error);
349				box-shadow: inset 0 0 0 1px var(--error);
