352				display: block;
353				color: var(--error);
354				font-size: 0.875rem;
355				font-weight: 500;
356			}
357			.error-message:not(:empty) {
358				margin-top: 0.25rem;
359			}
360			.counter {
361				display: flex;
362				flex-wrap: wrap;
363				gap: 1rem;
364				align-items: center;
365				margin: 1.5rem 0;
366			}
367			.counter output {
368				min-width: 3ch;
369				font-size: 1.5rem;
370				font-weight: 600;
371				font-variant-numeric: tabular-nums;
372				color: var(--accent);
373				text-align: center;
374			}
