388			textarea:focus {
389				outline: 2px solid var(--accent);
390				outline-offset: 2px;
391				border-color: var(--accent);
392			}
393			@media print {
394				:root {
395					color-scheme: light;
396					--text: #000;
397					--text-secondary: #333;
398					--background: #fff;
399					--surface: #fff;
400					--accent: #000;
401					--border: #999;
402					--border-control: #000;
403					--error: #000;
404					--success: #000;
405				}
406				.skip-link,
407				nav,
408				button,
409				.button,
410				.live-region {
411					display: none;
412				}
413				body {
414					display: block;
415					min-height: 0;
416					max-width: none;
417					padding: 0;
418				}
419				a {
420					color: inherit;
421					text-decoration: underline;
422				}
