434	</head>
435	<body>
436		<a class="skip-link" href="#main">Skip to content</a>
437		<header id="top">
438			<h1>Welcome</h1>
439			<nav aria-label="Page sections">
440				<ul>
441					<li><a href="#features">Features</a></li>
442					<li><a href="#examples">Examples</a></li>
443					<li><a href="#resources">Resources</a></li>
444				</ul>
445			</nav>
446		</header>
447		<main id="main" tabindex="-1">
448			<section aria-label="Introduction">
449				<p>This is a well-structured, accessible HTML5 document demonstrating modern best practices for semantic markup and inclusive design.</p>
450				<p>
451					It uses semantic landmarks, a skip link for keyboard navigation,
452					and CSS that adapts to your light or dark mode preference.
453				</p>
454				<p>
455					Text and link colors meet WCAG AA contrast in both themes, type scales
456					with your browser's font size, and motion respects your system settings.
457				</p>
458			</section>
459	
460			<section aria-labelledby="features">
461				<h2 id="features">Features</h2>
462				<ul>
463					<li>Semantic HTML structure with proper landmarks</li>
464					<li>Keyboard accessible navigation and focus management</li>
465					<li>Dark mode support with custom color schemes</li>
466					<li>Responsive typography using modern CSS</li>
467					<li>Print-friendly styles for better readability</li>
468					<li>WCAG AA contrast compliance in all color modes</li>
469				</ul>
470			</section>
471	
472			<section aria-labelledby="examples">
473				<h2 id="examples">Examples</h2>
474				<article class="card">
475					<h3>Component Cards</h3>
476					<p>Card components are useful for organizing related content. They include a subtle border and padding for visual separation.</p>
477					<a class="button" href="#resources">Learn more<span class="visually-hidden"> about accessibility resources</span></a>
478				</article>
479	
480				<article class="card">
481					<h3>Interactive Elements</h3>
482					<p>Buttons and links are fully accessible with clear focus states. All interactive elements include visible focus indicators and proper ARIA labels.</p>
483					<p><strong>Keyboard navigation:</strong> Use <kbd>Tab</kbd> to move forward, <kbd>Shift</kbd>+<kbd>Tab</kbd> to move backward, and <kbd>Enter</kbd> to activate.</p>
484				</article>
485	
486				<article class="card">
487					<h3>Accessible Form</h3>
488					<form id="contact-form" novalidate>
489						<p class="form-hint">Fields marked * are required.</p>
490						<div class="field">
491							<label for="email">Email <span aria-hidden="true">*</span></label>
492							<input type="email" id="email" name="email" autocomplete="email" spellcheck="false" autocapitalize="none" required aria-describedby="email-help">
493							<span id="email-error" class="error-message" role="alert"></span>
494							<small id="email-help" class="form-hint">For example, name@example.com</small>
495						</div>
496						<div class="field">
497							<label for="message">Message</label>
498							<textarea id="message" name="message" rows="4" maxlength="2000" aria-describedby="message-help"></textarea>
499							<small id="message-help" class="form-hint">Up to 2,000 characters.</small>
500						</div>
501						<button type="submit">Send message</button>
502						<p id="form-status" role="status"></p>
503					</form>
504				</article>
505	
506				<article class="card">
507					<h3>Live Region Example</h3>
508					<p>Click the button to announce a message using a live region. This demonstrates how screen readers are notified of dynamic updates.</p>
509					<button id="announce" type="button">Announce message</button>
510					<div class="live-region" aria-live="polite" aria-atomic="true">
511						<span id="live-message"></span>
512					</div>
513				</article>
514	
515				<article class="card">
516					<h3>Interactive Counter</h3>
517					<p>This counter demonstrates state management and ARIA live regions for accessible dynamic content.</p>
518					<div class="counter">
519						<button id="decrease" type="button" aria-label="Decrease count by 1">−</button>
520						<output id="count" aria-live="polite" aria-label="Current count is">0</output>
521						<button id="increase" type="button" aria-label="Increase count by 1">+</button>
522						<button id="reset" type="button" aria-label="Reset count to zero">Reset</button>
523					</div>
524					<div class="live-region" aria-live="polite" aria-atomic="true">
525						<span id="count-message"></span>
526					</div>
527				</article>
528			</section>
529	
530			<section aria-labelledby="resources">
531				<h2 id="resources">Resources</h2>
532				<p>Want to learn more about web accessibility and semantic HTML? Check out these resources:</p>
533				<ul>
534					<li><a href="https://www.w3.org/WAI/WCAG22/quickref/" target="_blank" rel="noopener noreferrer">WCAG 2.2 Quick Reference<span class="visually-hidden"> (opens in new tab)</span></a></li>
535					<li><a href="https://html.spec.whatwg.org/" target="_blank" rel="noopener noreferrer">HTML Living Standard<span class="visually-hidden"> (opens in new tab)</span></a></li>
536					<li><a href="https://www.a11y-101.com/" target="_blank" rel="noopener noreferrer">A11y 101<span class="visually-hidden"> (opens in new tab)</span></a></li>
537				</ul>
538			</section>
539		</main>
540		<footer>
541			<nav aria-label="Footer links">
542				<ul>
543					<li><a href="#top">Back to top</a></li>
544					<li><a href="https://github.com" target="_blank" rel="noopener noreferrer">GitHub<span class="visually-hidden"> (opens in new tab)</span></a></li>
545				</ul>
546			</nav>
547			<p><small>&copy; <span id="copyright-year">2026</span>. All rights reserved.</small></p>
548		</footer>
549		<script>
550			const copyrightYear = document.getElementById('copyright-year');
551			if (copyrightYear) {
552				copyrightYear.textContent = String(new Date().getFullYear());
553			}
554	
555			const messages = [
556				"This update was announced to screen readers!",
557				"Dynamic content updates work with aria-live regions.",
558				"Live regions are essential for accessible web apps.",
559				"Try this with a screen reader like NVDA or JAWS!"
560			];
561			let nextMessage = 0;
562			let count = 0;
563			const announceBtn = document.getElementById('announce');
564			const contactForm = document.getElementById('contact-form');
565			const emailInput = document.getElementById('email');
566			const formStatus = document.getElementById('form-status');
567			const countDisplay = document.getElementById('count');
568			const countMessage = document.getElementById('count-message');
569			const decreaseBtn = document.getElementById('decrease');
570			const increaseBtn = document.getElementById('increase');
571			const resetBtn = document.getElementById('reset');
572	
573			const updateCountDisplay = () => {
574				countDisplay.textContent = count;
575				countMessage.textContent = `Count is now ${count}.`;
576			};
577	
578			if (decreaseBtn) {
579				decreaseBtn.addEventListener('click', () => {
580					count--;
581					updateCountDisplay();
582				});
583			}
584	
585			if (increaseBtn) {
586				increaseBtn.addEventListener('click', () => {
587					count++;
588					updateCountDisplay();
589				});
590			}
591	
592			if (resetBtn) {
593				resetBtn.addEventListener('click', () => {
594					count = 0;
595					updateCountDisplay();
596				});
597			}
598	
599			if (announceBtn) {
600				announceBtn.addEventListener('click', () => {
601					document.getElementById('live-message').textContent = messages[nextMessage];
602					nextMessage = (nextMessage + 1) % messages.length;
603				});
604			}
605	
606			if (contactForm) {
607				const emailError = document.getElementById('email-error');
608	
609				const validateEmail = () => {
610					let message = '';
611					if (emailInput.validity.valueMissing) {
612						message = 'Enter your email address.';
613					} else if (!emailInput.validity.valid) {
614						message = 'Enter an email address in the format name@example.com.';
615					}
616					emailError.textContent = message;
617					if (message) {
618						emailInput.setAttribute('aria-invalid', 'true');
619						emailInput.setAttribute('aria-describedby', 'email-error email-help');
620					} else {
621						emailInput.removeAttribute('aria-invalid');
622						emailInput.setAttribute('aria-describedby', 'email-help');
623					}
624					return !message;
625				};
626	
627				emailInput.addEventListener('blur', () => {
628					if (emailInput.value || emailInput.hasAttribute('aria-invalid')) {
629						validateEmail();
630					}
631				});
632	
633				emailInput.addEventListener('input', () => {
634					if (emailInput.hasAttribute('aria-invalid')) {
635						validateEmail();
636					}
637				});
638	
639				contactForm.addEventListener('input', () => {
640					formStatus.textContent = '';
641				});
